import os

KEYWORDS = ["create_", "update_", "delete_", "save_", "write_", "POST", "PUT", "PATCH"]

def search_keywords():
    for root, _, files in os.walk('app'):
        for file in files:
            if file.endswith('.py') and file != 'auth.py':
                filepath = os.path.join(root, file)
                with open(filepath, 'r') as f:
                    content = f.read()
                found = [kw for kw in KEYWORDS if kw in content]
                if found:
                    print(f"{filepath}: found {found}")

if __name__ == '__main__':
    search_keywords()

import os
import ast

def main():
    for root, _, files in os.walk('app'):
        for file in files:
            if file.endswith('.py') and file != 'auth.py':
                filepath = os.path.join(root, file)
                with open(filepath, 'r') as f:
                    content = f.read()
                if 'legacy_auth' in content:
                    lines = content.splitlines()
                    tree = ast.parse(content, filepath)
                    for node in ast.walk(tree):
                        if isinstance(node, ast.FunctionDef):
                            calls_legacy = False
                            for child in ast.walk(node):
                                if isinstance(child, ast.Call) and isinstance(child.func, ast.Name) and child.func.id == 'legacy_auth':
                                    calls_legacy = True
                                    break
                            if calls_legacy:
                                start = node.lineno
                                end = getattr(node, 'end_lineno', len(lines))
                                func_text = "\n".join(lines[start-1:end])
                                print("=" * 40)
                                print(f"File: {filepath}, Function: {node.name}")
                                print(func_text)

if __name__ == '__main__':
    main()

